import{_ as i,o as t,c as e,a3 as l}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"Ollama LAN 접근","description":"OLLAMA_HOST=0.0.0.0과 방화벽으로 폰 MiniTavern이 PC Ollama에 LAN 접속.","frontmatter":{"title":"Ollama LAN 접근","description":"OLLAMA_HOST=0.0.0.0과 방화벽으로 폰 MiniTavern이 PC Ollama에 LAN 접속.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"Ollama LAN 접근 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OLLAMA_HOST=0.0.0.0과 방화벽으로 폰 MiniTavern이 PC Ollama에 LAN 접속."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/ollama/lan"}]]},"headers":[],"relativePath":"ko/ollama/lan.md","filePath":"ko/ollama/lan.md","lastUpdated":1787224147000}'),s={name:"ko/ollama/lan.md"};function n(o,a,h,r,p,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="ollama-lan-접근" tabindex="-1">Ollama LAN 접근 <a class="header-anchor" href="#ollama-lan-접근" aria-label="Permalink to &quot;Ollama LAN 접근&quot;">​</a></h1><p>기본적으로 Ollama는 로컬만 리슨하는 경우가 많습니다. 폰→PC에는 <strong>모든 NIC</strong>（<code>0.0.0.0</code>）리슨과 방화벽 개방이 필요합니다.</p><h2 id="ollama-host-설정" tabindex="-1"><code>OLLAMA_HOST</code> 설정 <a class="header-anchor" href="#ollama-host-설정" aria-label="Permalink to &quot;`OLLAMA_HOST` 설정&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>시작 → 「환경 변수」→ 「시스템 환경 변수 편집」→ 「환경 변수」.</li><li>사용자 또는 시스템 변수에 새로 만들기:</li></ol><table tabindex="0"><thead><tr><th>이름</th><th>값</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>저장 후 Ollama <strong>완전 종료·재시작</strong>（트레이에서 종료 후 실행）.</li></ol><p>PowerShell（현재 세션 임시）:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 그다음 ollama 앱/서비스 재시작</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>임시（현재 터미널）:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>Ollama 앱 종료·재실행. 재부팅 후 사라지면 shell 설정 또는 LaunchAgent; 또는:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>해당 환경에서 Ollama 서비스 기동. 가장 확실: <strong>환경 변수 설정 후 Ollama 재시작</strong>.</p><h2 id="방화벽-포트-11434" tabindex="-1">방화벽 포트 11434 <a class="header-anchor" href="#방화벽-포트-11434" aria-label="Permalink to &quot;방화벽 포트 11434&quot;">​</a></h2><ul><li><strong>Windows</strong>: 설정 → 개인정보 및 보안 → Windows 보안 → 방화벽 → 앱 허용; 또는 TCP <code>11434</code> 인바운드.</li><li><strong>macOS</strong>: 시스템 설정 → 네트워크 → 방화벽; 첫 접근 시 Ollama 허용 또는 포트.</li></ul><h2 id="lan-검증" tabindex="-1">LAN 검증 <a class="header-anchor" href="#lan-검증" aria-label="Permalink to &quot;LAN 검증&quot;">​</a></h2><ol><li>PC IP（<a href="./../quickstart#step-4-pc-lan-ip">퀵스타트 Step 4</a>）.</li><li><strong>같은 Wi‑Fi의 다른 기기</strong> 브라우저:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>열리거나 Ollama 응답이면 LAN OK.</p><h2 id="minitavern용-주소" tabindex="-1">MiniTavern용 주소 <a class="header-anchor" href="#minitavern용-주소" aria-label="Permalink to &quot;MiniTavern용 주소&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>주의:</p><ul><li>LAN IP, <strong><code>localhost</code> 금지</strong></li><li><code>/v1</code> 접미 권장（OpenAI 호환）</li></ul><h2 id="다음" tabindex="-1">다음 <a class="header-anchor" href="#다음" aria-label="Permalink to &quot;다음&quot;">​</a></h2><p><a href="./../connect-app/minitavern">MiniTavern 설정</a></p>',27)])])}const m=i(s,[["render",n]]);export{k as __pageData,m as default};
